"""Render the actual standard recipe using the platform's task-card visual style."""
from pathlib import Path
from html import escape
import hashlib,json,yaml
ROOT=Path(__file__).resolve().parents[1]
recipe=ROOT/'runtime/src/chip_nebula/configs/recipes/specification-to-gds.yaml'
a=yaml.safe_load(recipe.read_text())
groups=[('Specification / CSIR',['analyze-source','generate-design-document','generate-csir-draft']),('Independent closure',['review-requirements-closure','spec-compiler','consolidate-spec-decisions','freeze-specification-baseline']),('Physical assumptions',['propose-project-constraint-decisions','consolidate-project-decisions','generate-project-constraints','freeze-project-constraints']),('Acceptance contract',['generate-acceptance-plan','freeze-acceptance-plan']),('RTL / integration',['rtl-implementation','full-design-integration']),('Execution evidence',['functional-performance-verify','synthesize']),('Physical closure',['pnr','gds-export']),('Repair owner',['failure-analysis'])]
assert a['tasks']['rtl-implementation']['inputs']['specification']['from']=='$tasks.freeze-specification-baseline.outputs.specification'
assert a['tasks']['full-design-integration']['inputs']['constraints']['from']=='$tasks.freeze-project-constraints.outputs.constraints'
assert a['tasks']['functional-performance-verify']['inputs']['acceptance']['from']=='$tasks.freeze-acceptance-plan.outputs.acceptance'
assert len(a['tasks'])==20 and {t for _,ts in groups for t in ts}==set(a['tasks'])
parts=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 1040" role="img" aria-labelledby="title desc"><title id="title">ChipWave standard specification-to-GDS workflow</title><desc id="desc">Twenty actual tasks grouped into eight panels. Independent compiler and review gates freeze specification, constraints and acceptance. Failure triage returns to an existing owner. Outer skill evolution is not measured.</desc><defs><pattern id="dots" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="#334155"/></pattern><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#7dd3fc"/></marker><marker id="retry" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#2dd4bf"/></marker></defs><rect width="1600" height="1040" fill="#0f172a"/><rect width="1600" height="1040" fill="url(#dots)"/><g font-family="Arial,sans-serif"><text x="32" y="38" fill="#f8fafc" font-size="25" font-weight="bold">STANDARD SPECIFICATION → GDS · 20 ACTUAL TASKS</text><text x="32" y="68" fill="#cbd5e1" font-size="17">Independent acceptance gates; delegated choices are recorded, not independent human signoff.</text>']
positions=[(32+i*392,100) for i in range(4)]+[(32+i*392,480) for i in range(4)]
for (label,tasks),(x,y) in zip(groups,positions):
 parts.append(f'<rect x="{x}" y="{y}" width="360" height="310" rx="12" fill="#172b46" stroke="#38bdf8"/><text x="{x+14}" y="{y+30}" fill="#e0f2fe" font-size="20" font-weight="bold">{escape(label)}</text>')
 for n,t in enumerate(tasks):
  yy=y+65+n*55; role=a['tasks'][t].get('role','tool')
  parts.append(f'<text x="{x+14}" y="{yy}" fill="#f8fafc" font-size="16">{escape(t)}</text><text x="{x+14}" y="{yy+20}" fill="#94a3b8" font-size="13">{escape(role)}</text>')
 tags={'Specification / CSIR':'design document + typed CSIR','Independent closure':'review + compiler + spec freeze','Physical assumptions':'decisions + SDC + freeze','Acceptance contract':'traceable checks + freeze','RTL / integration':'versioned source delivery','Execution evidence':'fixed checkers + mapped netlist','Physical closure':'STA / electrical / DRC / LVS / GDS','Repair owner':'evidence → existing responsible task'}
 parts.append(f'<rect x="{x+12}" y="{y+267}" width="336" height="30" rx="6" fill="#4c1d95"/><text x="{x+20}" y="{y+287}" fill="#ddd6fe" font-size="14">{escape(tags[label])}</text>')
for row in (100,480):
 for i in range(3):
  if row==480 and i==2:continue
  xx=392+i*392;parts.append(f'<path d="M{xx} {row+150} L{xx+32} {row+150}" stroke="#7dd3fc" stroke-width="2" marker-end="url(#arrow)"/>')
parts.append('<path d="M1388 410 L1388 470 L604 470 L604 480" fill="none" stroke="#7dd3fc" stroke-width="2" marker-end="url(#arrow)"/><path d="M604 410 L604 430 L212 430 L212 480" fill="none" stroke="#7dd3fc" stroke-width="2" marker-end="url(#arrow)"/><path d="M996 410 L996 450 L320 450 L320 480" fill="none" stroke="#7dd3fc" stroke-width="2" marker-end="url(#arrow)"/><path d="M1160 640 L1208 640" stroke="#2dd4bf" stroke-width="2" stroke-dasharray="6 4" marker-end="url(#retry)"/><path d="M1388 790 L1388 834 L212 834 L212 790" fill="none" stroke="#2dd4bf" stroke-width="2" marker-end="url(#retry)"/><path d="M212 834 L16 834 L16 250 L32 250" fill="none" stroke="#2dd4bf" stroke-width="2" stroke-dasharray="6 4" marker-end="url(#retry)"/><text x="410" y="825" fill="#5eead4" font-size="17">Failure feedback → evidence-based triage → same task owner → fresh gates</text><rect x="32" y="860" width="1536" height="140" rx="12" fill="#102a2e" stroke="#2dd4bf" stroke-dasharray="7 5"/><text x="50" y="891" fill="#5eead4" font-size="20" font-weight="bold">OUTER RSI EXTENSION · NOT MEASURED IN THIS CASE</text><text x="50" y="926" fill="#ccfbf1" font-size="18">Retained failures → proposed versioned skill change → held-out evaluation → release decision → future frozen workflows</text><text x="50" y="961" fill="#cbd5e1" font-size="16">The observed valid-token CSIR repair is a same-case correction; it does not establish recursive learning across unseen designs.</text><text x="32" y="1025" fill="#94a3b8" font-size="15">Grouped diagram: spec → RTL in parallel with constraints; integration consumes constraints; verification also requires acceptance.</text></g></svg>')
(ROOT/'figures/platform_standard.svg').write_text(''.join(parts))
(ROOT/'figures/platform_standard.source.json').write_text(json.dumps({'recipe':str(recipe.relative_to(ROOT)),'recipe_sha256':hashlib.sha256(recipe.read_bytes()).hexdigest(),'actual_task_count':20,'task_groups':groups,'scope':'Grouped task roles and gates; no live state or successful physical-result assertion','rsi_heldout_evaluation_executed':False},indent=2)+'\n')
print('STANDARD_WORKFLOW_DIAGRAM_PASS: all 20 actual tasks, roles and groups represented')
